for f in D['findings']:
 md += [f"### {f['id']} · {f['title']}",'',f"**{f['refs']} · {f['release']} · {f['size']} · {f['status']}**",'','**Observed:** '+f['observed'],'','**Why it matters:** '+f['impact'],'','**Proposed:** '+f['proposal'],'','Evidence: '+', '.join(f'[{n}](screenshots/{n}.png)' for n in f['evidence']),'']
md+=['## Every parked item has a destination','','Later owner rulings override older roadmap paragraphs; closed work remains a regression boundary.','','| Item | Disposition |','|---|---|']+[f'| {k} | {v} |' for k,v in D['mapping']]
