md+=['',scope_notes,'',acceptance,'','## One batch of owner rulings','','Reply “Q1–Q8 as recommended” or list exceptions. Already-ruled directions are preserved. These questions settle remaining boundaries; no implementation or merge begins from this document alone.','']
for k,title,body in D['rulings']:md += [f'### {k} · {title}','',body,'']
(A/'AUDIT.md').write_bytes(('\n'.join(md).rstrip()+'\n').encode())
css='''*{box-sizing:border-box}html{scroll-padding-top:72px}body{margin:0;background:#eee7d7;color:#28231e;font:17px/1.6 system-ui,sans-serif}main{max-width:1040px;margin:auto;padding:24px 18px 70px}h1,h2,h3{font-family:Georgia,serif;line-height:1.2}h1{font-size:clamp(2rem,6vw,3.4rem)}h2{margin-top:40px}h3{font-size:1.25rem}p,li,dd{overflow-wrap:anywhere}a{color:#842e28}nav{position:sticky;top:0;background:#f8f3e7f5;border-bottom:1px solid #c5b99a;z-index:2;padding:9px;display:flex;gap:8px;overflow-x:auto}nav a{white-space:nowrap;padding:6px 10px;border:1px solid #bcae91;border-radius:20px;font-size:14px;text-decoration:none}.lead,.finding,.scope,.ruling{background:#fbf7ed;border:1px solid #c8b99a;border-radius:8px;padding:18px;margin:18px 0}.lead{border-left:5px solid #a4332a}.meta{font-size:14px;color:#635343}.badge{display:inline-block;background:#e9dfc8;padding:3px 9px;border-radius:4px;margin:3px 4px 3px 0;font-size:14px}details{border-top:1px solid #d9cfb7;margin-top:12px}summary{cursor:pointer;padding:12px 0;min-height:44px}figure{margin:16px 0}img{display:block;max-width:100%;max-height:900px;width:auto;height:auto;margin:auto;border:1px solid #ccc}figcaption{font-size:13px;text-align:center;overflow-wrap:anywhere}dt{font-weight:700;margin-top:16px}dd{margin:4px 0 0;padding-bottom:12px;border-bottom:1px solid #d9cfb7}.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:14px}.gallery figure{background:#faf6ec;padding:8px}@media print{nav{position:static}.finding,.ruling{break-inside:avoid}}'''
h=['<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Phase 15 UI consistency audit</title><style>'+css+'</style></head><body>','<nav aria-label="Audit sections">'+''.join(f'<a href="#{i}">{t}</a>' for i,t in [('summary','Overview'),('findings','Findings'),('mapping','Backlog'),('gallery','Evidence'),('scope','Scope'),('rulings','Rulings')])+'</nav><main>','<header id="summary"><p class="meta">L5R 4e · 31 October 2026 · Codex · Step 3</p><h1>Phase 15<br>UI consistency audit</h1><div class="lead">'+e(intro)+'</div></header>','<h2>Method and limits</h2><ul>'+''.join('<li>'+e(x)+'</li>' for x in method)+'</ul>','<h2>QA: first-pass goal not achieved</h2><dl>'+''.join('<dt>'+e(k)+'</dt><dd>'+e(v)+'</dd>' for k,v in qa)+'</dl>','<h2 id="findings">36 findings</h2><p>Sizes: S = bounded presentation; M = shared/multi-screen interaction; L = functional state or print layout.</p>']
for f in D['findings']:
 h+=['<article class="finding" id="'+f['id']+'"><h3>'+e(f['id']+' · '+f['title'])+'</h3><p>'+''.join('<span class="badge">'+e(x)+'</span>' for x in [f['refs'],f['release'],f['size']])+'</p><p class="meta">'+e(f['status'])+'</p>'+''.join('<p><b>'+k+':</b> '+e(f[v])+'</p>' for k,v in [('Observed','observed'),('Why it matters','impact'),('Proposed','proposal')])+'<details><summary>View screenshot evidence</summary>'+''.join('<a href="#img-'+n+'">'+e(n)+'</a><br>' for n in f['evidence'])+'</details></article>']
h+=['<h2 id="mapping">Every parked item has a destination</h2><p>Later rulings override older paragraphs; closed work remains a regression boundary.</p><dl>'+''.join('<dt>'+e(k)+'</dt><dd>'+e(v)+'</dd>' for k,v in D['mapping'])+'</dl>','<h2 id="gallery">Evidence gallery</h2><p>All images are embedded. Captions match original PNGs. Existing app, not mock-ups.</p><div class="gallery">']
for p in shots:
 im=Image.open(p).convert('RGB');im.thumbnail((1200,1800));b=io.BytesIO();im.save(b,format='WEBP',quality=84)
 h+=['<figure id="img-'+p.stem+'"><img width="'+str(im.width)+'" height="'+str(im.height)+'" loading="lazy" alt="'+e(p.stem.replace('-',' '))+'" src="data:image/webp;base64,'+base64.b64encode(b.getvalue()).decode()+'"><figcaption>'+e(p.stem)+'</figcaption></figure>']
h+=['</div><h2>Usage and remote access</h2><p>'+e(usage_text)+'</p><h2 id="scope">Proposed release scopes and estimates</h2>']
for k,v,n in scopes:h+=['<section class="scope"><h3>'+e(k+' · '+n)+'</h3><p>'+e(v)+'</p></section>']
h+=['<p>'+e(scope_notes)+'</p><p>'+e(acceptance)+'</p><h2 id="rulings">One batch of owner rulings</h2><p>Reply <b>Q1–Q8 as recommended</b> or list exceptions. Already-ruled directions are preserved. This does not start implementation or authorize a merge.</p>']
for k,title,body in D['rulings']:h+=['<section class="ruling"><h3>'+e(k+' · '+title)+'</h3><p>'+e(body)+'</p></section>']
h+=['</main></body></html>']
(A/'AUDIT.html').write_bytes(('\n'.join(h)+'\n').encode())
print(json.dumps({'findings':len(D['findings']),'screenshots':len(shots),'html_bytes':(A/'AUDIT.html').stat().st_size,'markdown_bytes':(A/'AUDIT.md').stat().st_size}))
